<?php&#10&#10declare(strict_types=1);&#10&#10namespace Drupal\assessments\Model;&#10&#10/**&#10 * Defines the assessment model base class.&#10 */&#10abstract class AssessmentModelBase implements AssessmentModelInterface{&#10&#10  /**&#10   * Raw payload data for this model (structured object or UUID string wrapped upstream).&#10   */&#10  public function __construct(protected array $data) {}&#10&#10  /**&#10   * If this model references an existing entity by UUID, store it here.&#10   */&#10  protected ?string $existingUuid = NULL;&#10&#10  /**&#10   * Internal created entity ID after save.&#10   */&#10  protected ?string $createdId = NULL;&#10&#10  /**&#10   * Returns the bundle of the assessment_content entity.&#10   *&#10   * @return string&#10   *   The bundle machine name.&#10   */&#10  abstract protected function bundle(): string;&#10&#10  /**&#10   * Extracts the entity values from the data.&#10   *&#10   * @return array&#10   *   The entity values.&#10   */&#10  abstract protected function getEntityValues(): array;&#10&#10  /**&#10   * Loads an existing entity by UUID if possible.&#10   */&#10  protected function loadExistingByUuid(?string $uuid): ?\Drupal\Core\Entity\EntityInterface {&#10    if (!$uuid) {&#10      return NULL;&#10    }&#10    $storage = \Drupal::entityTypeManager()->getStorage('assessment_content');&#10    $result = $storage->loadByProperties(['uuid' => $uuid]);&#10    if ($result) {&#10      return reset($result) ?: NULL;&#10    }&#10    return NULL;&#10  }&#10&#10  /**&#10   * Returns the saved entity id (if any).&#10   */&#10  public function getSavedId(): ?string {&#10    return $this->createdId;&#10  }&#10&#10  /**&#10   * {@inheritdoc}&#10   */&#10  public function validate(): array {&#10    // If this represents an existing entity by UUID, skip creation validation.&#10    if (!empty($this->data['_uuid'])) {&#10      $entity = $this->loadExistingByUuid($this->data['_uuid']);&#10      if ($entity) {&#10        return [];&#10      }&#10    }&#10&#10    $entity = \Drupal::entityTypeManager()->getStorage('assessment_content')->create([&#10      'type' => $this->bundle(),&#10    ] + $this->getEntityValues());&#10    return $entity->validate();&#10  }&#10&#10  /**&#10   * {@inheritdoc}&#10   */&#10  public function save(): void {&#10    // If payload references an existing entity via _uuid, try loading it and return.&#10    if (!empty($this->data['_uuid'])) {&#10      $existing = $this->loadExistingByUuid($this->data['_uuid']);&#10      if ($existing) {&#10        $this->createdId = (string) $existing->id();&#10        return;&#10      }&#10    }&#10&#10    $values = ['type' => $this->bundle(), 'created' => REQUEST_TIME, 'uid' => \Drupal::currentUser()->id()] + $this->getEntityValues();&#10    $storage = \Drupal::entityTypeManager()->getStorage('assessment_content');&#10    $entity = $storage->create($values);&#10    $entity->save();&#10    $this->createdId = (string) $entity->id();&#10  }&#10&#10}&#10